// Package fw holds the GPU firmware's data structures: their layouts per
// GPU generation and firmware version (generated by tools/agxlayout from
// drm/asahi's fw/*.rs, layout_gen.go) and a writer that fills them by
// field name, so a structure is built the same way for 12.3 and 13.5.
package fw

import (
	"encoding/binary"
	"fmt"
	"math"
	"strings"
)

// Field is one field of a structure.
type Field struct {
	Name      string
	Off, Size int
	Type      string // the Rust type
}

// Layout is a structure's layout.
type Layout struct {
	Size, Align int
	Fields      []Field
}

// Layouts are all structures for one (generation, firmware) pair, by
// "module.Name" (module = drm/asahi's fw file: initdata, channels, …).
type Layouts map[string]Layout

// all is every layout table, to tell a field another version has from a typo.
var all = []Layouts{G1312_3, G1313_5}

// For returns the layouts for a GPU generation and firmware compat.
func For(gen int, compat [3]uint32) (Layouts, error) {
	switch {
	case gen == 13 && compat == [3]uint32{12, 3, 0}:
		return G1312_3, nil
	case gen == 13 && compat == [3]uint32{13, 5, 0}:
		return G1313_5, nil
	}
	return nil, fmt.Errorf("fw: no layouts for G%d firmware %d.%d.%d", gen, compat[0], compat[1], compat[2])
}

// Get returns a structure's layout; it panics on an unknown name (a typo
// in the driver, caught by its tests).
func (l Layouts) Get(name string) Layout {
	s, ok := l[name]
	if !ok {
		panic("fw: no structure " + name)
	}
	return s
}

// Field returns a field; ok is false if the field doesn't exist in this
// version (a #[ver] field of another version).
func (s Layout) Field(name string) (Field, bool) {
	for _, f := range s.Fields {
		if f.Name == name {
			return f, true
		}
	}
	return Field{}, false
}

// Off returns a field's offset, or panics.
func (s Layout) Off(name string) int {
	f, ok := s.Field(name)
	if !ok {
		panic("fw: no field " + name)
	}
	return f.Off
}

// Has reports whether the field exists in this version.
func (s Layout) Has(name string) bool { _, ok := s.Field(name); return ok }

// Writer fills one structure in place (little endian, as the firmware).
// Writes to a field this version lacks are dropped, so a builder can set
// the fields of every version; a field no version has panics (a typo), as
// does a write that doesn't fit the field.
type Writer struct {
	Struct string
	L      Layout
	B      []byte // the structure's bytes
}

// Writer returns a writer for structure name over b (at least its size).
func (l Layouts) Writer(name string, b []byte) *Writer {
	s := l.Get(name)
	if len(b) < s.Size {
		panic(fmt.Sprintf("fw: %s needs %#x bytes, have %#x", name, s.Size, len(b)))
	}
	return &Writer{Struct: name, L: s, B: b[:s.Size]}
}

func (w *Writer) field(name string) (Field, bool) {
	if f, ok := w.L.Field(name); ok {
		return f, true
	}
	for _, l := range all {
		if s, ok := l[w.Struct]; ok && s.Has(name) {
			return Field{}, false // another version's field
		}
	}
	panic(fmt.Sprintf("fw: %s has no field %s in any version", w.Struct, name))
}

// At returns a writer for a nested structure field (or nil if this
// version lacks the field: every write through a nil Writer is dropped).
func (w *Writer) At(field, structName string, l Layouts) *Writer {
	if w == nil {
		return nil
	}
	f, ok := w.field(field)
	if !ok {
		return nil
	}
	s := l.Get(structName)
	if f.Size%s.Size != 0 {
		panic(fmt.Sprintf("fw: %s.%s (%d bytes) isn't %s (%d bytes)", w.Struct, field, f.Size, structName, s.Size))
	}
	return &Writer{Struct: structName, L: s, B: w.B[f.Off : f.Off+s.Size]}
}

// AtIndex is At for element i of an array of structures.
func (w *Writer) AtIndex(field string, i int, structName string, l Layouts) *Writer {
	if w == nil {
		return nil
	}
	f, ok := w.field(field)
	if !ok {
		return nil
	}
	s := l.Get(structName)
	off := f.Off + i*s.Size
	if f.Size%s.Size != 0 || i < 0 || off+s.Size > f.Off+f.Size {
		panic(fmt.Sprintf("fw: %s.%s[%d] of %s out of range", w.Struct, field, i, structName))
	}
	return &Writer{Struct: structName, L: s, B: w.B[off : off+s.Size]}
}

// scalarSize is the size of an array's (innermost) element type.
func scalarSize(typ string) int {
	t := strings.TrimSpace(typ)
	switch {
	case strings.HasPrefix(t, "Array<") && strings.HasSuffix(t, ">"):
		inner := t[len("Array<") : len(t)-1]
		if i := strings.Index(inner, ","); i >= 0 {
			return scalarSize(inner[i+1:])
		}
		return 0
	case strings.HasPrefix(t, "[") && strings.HasSuffix(t, "]"):
		return scalarSize(strings.SplitN(t[1:len(t)-1], ";", 2)[0])
	}
	switch strings.TrimSuffix(t, "::ver") {
	case "u8", "i8", "bool":
		return 1
	case "u16", "i16":
		return 2
	case "u32", "i32", "F32", "U32", "AtomicU32", "AtomicI32", "EventValue":
		return 4
	case "u64", "i64", "U64", "AtomicU64", "usize":
		return 8
	}
	if strings.HasPrefix(t, "GpuPointer") || strings.HasPrefix(t, "GpuWeakPointer") || strings.HasPrefix(t, "Option<Gpu") {
		return 8
	}
	return 0
}

// isF32 reports whether a field (or its array element) is an F32.
func isF32(typ string) bool {
	t := strings.TrimSuffix(strings.TrimRight(typ, "> "), "::ver")
	return t == "F32" || strings.HasSuffix(t, " F32") || strings.HasSuffix(t, ",F32")
}

func (w *Writer) slot(name string, i int) []byte {
	b, _ := w.slotType(name, i)
	return b
}

func (w *Writer) slotType(name string, i int) ([]byte, bool) {
	if w == nil {
		return nil, false
	}
	f, ok := w.field(name)
	if !ok {
		return nil, false
	}
	return w.slotOf(f, name, i), isF32(f.Type)
}

func (w *Writer) slotOf(f Field, name string, i int) []byte {
	size := f.Size
	if strings.HasPrefix(f.Type, "Array<") || strings.HasPrefix(f.Type, "[") {
		size = scalarSize(f.Type)
	} else if i != 0 {
		panic(fmt.Sprintf("fw: %s.%s isn't an array", w.Struct, name))
	}
	off := f.Off + i*size
	if size == 0 || size > 8 || i < 0 || off+size > f.Off+f.Size {
		panic(fmt.Sprintf("fw: %s.%s (%s): no element %d", w.Struct, name, f.Type, i))
	}
	return w.B[off : off+size]
}

func put(b []byte, v uint64) {
	switch len(b) {
	case 1:
		b[0] = uint8(v)
	case 2:
		binary.LittleEndian.PutUint16(b, uint16(v))
	case 4:
		binary.LittleEndian.PutUint32(b, uint32(v))
	case 8:
		binary.LittleEndian.PutUint64(b, v)
	}
}

// Set writes an integer (any width; negative values two's complement).
// Into an F32 field it writes the value as a float, as Rust's .into().
func (w *Writer) Set(field string, v int64) { w.SetAt(field, 0, v) }

// SetAt writes element i of an array (multi-dimensional arrays are
// flattened, row-major).
func (w *Writer) SetAt(field string, i int, v int64) {
	if b, f32 := w.slotType(field, i); b != nil {
		if f32 {
			put(b, uint64(math.Float32bits(float32(v))))
		} else {
			put(b, uint64(v))
		}
	}
}

// F32 writes a float field (the firmware's F32 is an IEEE single).
func (w *Writer) F32(field string, v float32) { w.F32At(field, 0, v) }

// F32At writes element i of a float array. An integer field panics.
func (w *Writer) F32At(field string, i int, v float32) {
	if b, f32 := w.slotType(field, i); b != nil {
		if !f32 {
			panic(fmt.Sprintf("fw: %s.%s isn't an F32", w.Struct, field))
		}
		put(b, uint64(math.Float32bits(v)))
	}
}

// Ptr writes a GPU pointer (a GPU virtual address).
func (w *Writer) Ptr(field string, va uint64) {
	if b := w.slot(field, 0); b != nil {
		if len(b) != 8 {
			panic(fmt.Sprintf("fw: %s.%s isn't a pointer", w.Struct, field))
		}
		put(b, va)
	}
}

// Fill sets every element of an integer array to v.
func (w *Writer) Fill(field string, v int64) {
	if w == nil {
		return
	}
	f, ok := w.field(field)
	if !ok {
		return
	}
	for i := 0; i < f.Size/scalarSize(f.Type); i++ {
		w.SetAt(field, i, v)
	}
}

// Len is the number of elements of a scalar array field in this version
// (0 if the field is absent, 1 for a non-array or an array of structures:
// divide the field size by the structure's for those).
func (w *Writer) Len(field string) int {
	if w == nil {
		return 0
	}
	f, ok := w.field(field)
	if !ok {
		return 0
	}
	if s := scalarSize(f.Type); s > 0 {
		return f.Size / s
	}
	return 1
}
